     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        Room room = rooms.find(request.roomNumber())
    35	                .orElseThrow(() -> new HotelException(
    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    37	        if (request.guests() > room.capacity()) {
    38	            throw new HotelException(
    39	                    ErrorCode.CAPACITY_EXCEEDED,
    40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    41	        }
    42	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    43	            throw new HotelException(
    44	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    45	        }
    46	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    47	        return store.add(request, price);
    48	    }
    49	
    50	    public Reservation find(long reservationId) {
    51	        return store.find(reservationId)
    52	                .orElseThrow(() -> new HotelException(
    53	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    54	    }
    55	
    56	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    57	    public synchronized Reservation confirm(long reservationId) {
    58	        Reservation reservation = find(reservationId);
    59	        if (reservation.status() != ReservationStatus.PENDING) {
    60	            throw notAllowed(reservation, "confirm");
    61	        }
    62	        reservation.confirmPayment();
    63	        store.update(reservation);
    64	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    65	        emailSender.send(
    66	                reservation.guest().email(),
    67	                "Reserva confirmada - " + HOTEL_NAME,
    68	                confirmationEmailBody(reservation, receipt));
    69	        return reservation;
    70	    }
    71	
    72	    /**
    73	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    74	     * reservation was never paid, so nothing comes back).
    75	     */
    76	    public synchronized Reservation cancel(long reservationId) {
    77	        Reservation reservation = find(reservationId);
    78	        if (reservation.status() != ReservationStatus.PENDING
    79	                && reservation.status() != ReservationStatus.CONFIRMED) {
    80	            throw notAllowed(reservation, "cancel");
    81	        }
    82	        BigDecimal refund = switch (reservation.ratePlan()) {
    83	            case STANDARD -> reservation.amountPaid();
    84	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    85	        };
    86	        reservation.cancel(refund);
    87	        store.update(reservation);
    88	        return reservation;
    89	    }
    90	
    91	    public synchronized Reservation checkIn(long reservationId) {
    92	        Reservation reservation = find(reservationId);
    93	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    94	            throw notAllowed(reservation, "check in");
    95	        }
    96	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    97	        store.update(reservation);
    98	        return reservation;
    99	    }
   100	
   101	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   102	    public synchronized ReservationReceipt checkOut(long reservationId) {
   103	        Reservation reservation = find(reservationId);
   104	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   105	            throw notAllowed(reservation, "check out");
   106	        }
   107	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   108	        store.update(reservation);
   109	        return new ReservationReceipt(reservation, roomOf(reservation));
   110	    }
   111	
   112	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   113	    public ReservationReceipt receiptCopy(long reservationId) {
   114	        Reservation reservation = find(reservationId);
   115	        if (!reservation.isPaid()) {
   116	            throw notAllowed(reservation, "issue a receipt for");
   117	        }
   118	        return new ReservationReceipt(reservation, roomOf(reservation));
   119	    }
   120	
   121	    private Room roomOf(Reservation reservation) {
   122	        return rooms.find(reservation.roomNumber()).orElseThrow();
   123	    }
   124	
   125	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   126	        return "Olá, " + reservation.guest().name() + "!\n\n"
   127	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   128	                + receipt.text() + "\n"
   129	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   130	                + "Até breve!\n";
   131	    }
   132	
   133	    private static HotelException notAllowed(Reservation reservation, String operation) {
   134	        return new HotelException(
   135	                ErrorCode.OPERATION_NOT_ALLOWED,
   136	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   137	    }
   138	}
